from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=1)
def compute_gof(input, i, j):
    n1 = n2 = n3 = n4 = n5 = n6 = n7 = n8 = 0
    if i > 0:     n1 = input[i - 1][j]
    if i < len(input) - 1: n2 = input[i + 1][j]
    if j > 0: n3 = input[i][j - 1]
    if j < len(input[0]) - 1: n4 = input[i][j + 1]
    if i > 0 and j > 0: n5 = input[i - 1][j - 1]
    if i > 0 and j < len(input[0]) - 1: n6 = input[i - 1][j + 1]
    if i < len(input) - 1 and j > 0: n7 = input[i + 1][j - 1]
    if i < len(input) - 1 and j < len(input[0]) - 1: n8 = input[i + 1][j + 1]

    if input[i][j] == 0:
        if n1 + n2 + n3 + n4 + n5 + n6 + n7 + n8 == 3:
            return 1
        else:
            return 0
    else:
        if n1 + n2 + n3 + n4 + n5 + n6 + n7 + n8 in [2, 3]:
            return 1
        else:
            return 0

def main(input):
    output = [[compute_gof(input, i, j) for j in range(len(input[0]))] for i in range(len(input))]
    output = compss_wait_on(output)
    return output
